#include <stdlib.h>    // getenv, system
#include <stdio.h>     // snprintf

const char* os_user_name()
{
#if defined(OS_WINDOWS)
    static char name[256 + 1];
    DWORD sz = 256 + 1;
    GetUserNameA(name, &sz);
    return name;
#elif defined(OS_POSIX)
    const char* name = getenv("USER");
    if (name != nullptr) return name;

    struct passwd *pw;
    uid_t uid;

    uid = geteuid();
    pw = getpwuid(uid);

    if (pw != nullptr) return pw->pw_name;
    return "unknown";
#endif
}

void open_url(const char* url)
{
    if (!url) return;

    /* static */ char buff[256];

#if defined(OS_WINDOWS)
    snprintf(buff, sizeof(buff), "explorer %s", url);
#elif defined(OS_LINUX)
    snprintf(buff, sizeof(buff), "xdg-open %s", url);
#elif defined(OS_APPLE)
    snprintf(buff, sizeof(buff), "open %s", url);
#endif

    system(buff);
}

#endif // !defined(SPFLIB_PLATFORM_IMPL)

