#define sprint(_buff, _buff_sz, _fmt, ...)                                                                      \
    do {                                                                                                        \
        __sprint(                                                                                               \
            _buff,                                                                                              \
            _buff_sz,                                                                                           \
            _fmt,                                                                                               \
            __N_VA_ARGS(__VA_ARGS__)__VA_OPT__(,)                                                               \
