#if defined(SPFLIB_FILEIO)

#if defined(OS_WINDOWS)
#   include <windows.h>
#   include <stdio.h>        // remove, fopen, fclose
#elif defined(OS_POSIX)
#   include <sys/types.h>    // uid_t
#   include <sys/stat.h>     // stat
#   include <sys/statvfs.h>  // statvfs
#   include <unistd.h>       // rmdir, geteuid
#   include <pwd.h>          // geteuid, getpwuid
#   include <stdlib.h>       // getenv
#   include <stdio.h>        // remove, fopen, fclose
#   include <time.h>         // time_t
#endif

#if !defined(SPFLIB_FILEIO_IMPL)

bool make_dir(const char* path);
bool delete_dir(const char* path);
bool dir_exists(const char* path);
const char* temp_dir();
bool file_exists(const char* path);
bool create_file(const char* path, bool override_existing);
bool delete_file(const char* path);
size_t file_time(const char* path);
size_t disk_free_space();

#else // !defined(SPFLIB_FILEIO_IMPL)

inline bool make_dir(const char* path)
{
#if defined(OS_WINDOWS)
    return CreateDirectoryA(path, nullptr);
#elif defined(OS_POSIX)
    struct stat st;

    if (stat(path, &st) == -1) {
        int r = mkdir(path, 0755);
        if (r == 0) return true;
    }

    return false;
#endif
}

inline bool delete_dir(const char* path)
{
#if defined(OS_WINDOWS)
    return RemoveDirectoryA(path);
#elif defined(OS_POSIX)
    return rmdir(path) == 0;
#endif
}

inline bool dir_exists(const char* path)
{
#if defined(OS_WINDOWS)
    DWORD attr = GetFileAttributes(path);
    return (attr != INVALID_FILE_ATTRIBUTES &&
           (attr & FILE_ATTRIBUTE_DIRECTORY));
#elif defined(OS_POSIX)
    return access(path, F_OK) == 0;
#endif
}

inline const char* temp_dir()
{
#if defined(OS_WINDOWS)
    static char path[256];
    GetTempPathA(256, path);
    return path;
#elif defined(OS_POSIX)
    // TODO: potentally find a better way of doing this
    const char* dir = getenv("TMPDIR");
    if (dir != nullptr) return dir;
    return "/tmp";
#endif
}

inline bool file_exists(const char* path)
{
#if defined(OS_WINDOWS)
    // return PathFileExistsA(path);
    DWORD attr = GetFileAttributes(path);
    return (attr != INVALID_FILE_ATTRIBUTES &&
          !(attr & FILE_ATTRIBUTE_DIRECTORY));
#elif defined(OS_POSIX)
    return access(path, F_OK) == 0;
#endif
}

bool create_file(const char* path, bool override_existing)
{
    if (!override_existing && file_exists(path)) return false;

    FILE* f = fopen(path, "w");

    if (f != nullptr) {
        fclose(f);
        return true;
    }

    fclose(f);
    return false;
}

inline bool delete_file(const char* path)
{
#if defined(OS_WINDOWS)
    return DeleteFileA(path);
#elif defined(OS_POSIX)
    return remove(path) == 0;
#endif
}

size_t file_time(const char* path)
{
#if defined(OS_WINDOWS)
    WIN32_FIND_DATAA data;
    HANDLE h = FindFirstFileA(path, &data);

    if (h == INVALID_HANDLE_VALUE) return 0;

    size_t UNIX_TIME_START = 0x019DB1DED53E8000;
    size_t TICKS_PER_SECOND = 10000000;

    FILETIME ft = data.ftLastWriteTime;

    LARGE_INTEGER li;
    li.LowPart  = ft.dwLowDateTime;
    li.HighPart = ft.dwHighDateTime;

    FindClose(&h);

    return (li.QuadPart - UNIX_TIME_START) / TICKS_PER_SECOND;
#elif defined(OS_POSIX)
    struct stat attr;
    int r = stat(path, &attr);
    return r == 0 ? (size_t)attr.st_mtime : 0;
#endif
}

size_t disk_free_space()
{
#if defined(OS_WINDOWS)
    ULARGE_INTEGER free_bytes;

    bool ok = GetDiskFreeSpaceExA(
        nullptr,    /* lpDirectoryName              */
        nullptr,    /* lpFreeBytesAvailableToCaller */
        nullptr,    /* lpTotalNumberOfBytes         */
        &free_bytes /* lpTotalNumberOfFreeBytes     */
    );

    if (!ok) return 0;
    return free_bytes.QuadPart;
#elif defined(OS_POSIX)
    struct statvfs st;

    int r = statvfs(".", &st);

    if (r == 0) return st.f_bfree * st.f_frsize;
    return 0;
#endif
}

#endif // !defined(SPFLIB_FILEIO_IMPL)

#endif // defined(SPFLIB_FILEIO)

