// --- allocators --- //

#if defined(SPFLIB_ALLOCATORS)

#if !defined(SPFLIB_MEMORY)
#   include <stdlib.h>    // malloc, free
#endif

// bump
typedef struct
{
    void*  data;
    size_t capacity;
    size_t pos_bytes;
} BumpAllocator;

#if !defined(SPFLIB_ALLOCATOR_IMPL)

BumpAllocator bump_new(size_t capacity);
void* bump_alloc(BumpAllocator* ac, size_t size);
void bump_reset(BumpAllocator* ac);
void bump_delete(BumpAllocator* ac);

#else // !defined(SPFLIB_ALLOCATOR_IMPL)

BumpAllocator bump_new(size_t capacity)
{
    BumpAllocator ac;

#if defined(SPFLIB_MEMORY)
    ac.data = mem_alloc(capacity);
#else
    ac.data = malloc(capacity);
#endif

#if defined(SPF_WILL_ASSERT)
    SPF_ASSERT(ac.data != nullptr, "Bump allocator failed to allocate memory.");
#endif

    ac.capacity  = capacity;
    ac.pos_bytes = 0;

    return ac;
}

inline void* bump_alloc(BumpAllocator* ac, size_t size)
{
    if (ac->data == nullptr) return nullptr;
    if ((size + ac->pos_bytes) >= ac->capacity) {
#if defined(SPF_WILL_ASSERT)
        SPF_ASSERT(0, "Bump allocator capacity exceeded.");
#endif
        return nullptr;
    }

    ac->data      += size;
    ac->pos_bytes += size;

    return ac->data;
}

inline void bump_reset(BumpAllocator* ac)
{
    ac->data      -= ac->pos_bytes;
    ac->pos_bytes  = 0;
}

inline void bump_delete(BumpAllocator* ac)
{
    ac->pos_bytes = 0;
    ac->capacity  = 0;

#if defined(SPFLIB_MEMORY)
    mem_free(ac->data);
#else
    free(ac->data);
#endif
    ac->data      = nullptr;
}

#endif // !defined(SPFLIB_ALLOCATOR_IMPL)

#endif // defined(SPFLIB_ALLOCATORS)

// --- color --- //

#if defined(SPFLIB_COLOR)

typedef struct
{
   u8 r, g, b, a;
} Color4;

#define COLOR4_TO_GL(_c) _c.r / 255.f, _c.g / 255.f, _c.b / 255.f, _c.a / 255.f

#define __Color4_Make(...) (Color4){ __VA_ARGS__ }
#define __Color4_Args(_1, _2, _3, _4, x, ...) x
#define Color4(...) __Color4_Args(__VA_ARGS__,                    \
                            __Color4_Make(__VA_ARGS__),           \
                            __Color4_Make(__VA_ARGS__, 255),      \
                            __Color4_Make(__VA_ARGS__, 255, 255), \
                            __Color4_Make(__VA_ARGS__, __VA_ARGS__, __VA_ARGS__, 255))

#if !defined(SPFLIB_COLOR_IMPL)

Color4 color_from_hex(u32 hex);
u32 color_to_hex(Color4 c);

#else // !defined(SPFLIB_COLOR_IMPL)

inline Color4 color_from_hex(u32 hex)
{
    Color4 c;

    c.r = (hex >> 24) & 0xFF;
    c.g = (hex >> 16) & 0xFF;
    c.b = (hex >> 8)  & 0xFF;
    c.a = (hex >> 0)  & 0xFF;

    return c;
}

inline u32 color_to_hex(Color4 c)
{
    return (u32)((u32)c.r << 24) | ((u32)c.g << 16) | ((u32)c.b << 8) | ((u32)c.a << 0);
}

#endif // !defined(SPFLIB_COLOR_IMPL)

#endif // defined(SPFLIB_COLOR)

