#if defined(SPFLIB_TEMP)

struct __TempStorage
{
    void*  data;
    size_t capacity;
    size_t pos_bytes;
} __temp_storage = {0};

#if !defined(SPFLIB_TEMP_CAPACITY)
#   define SPFLIB_TEMP_CAPACITY 2097152 /* 2 MB */
#endif

s32 __real_main(s32 argc, char** argv);

#define main(...)                          \
    main(s32 argc, char** argv)            \
    {                                      \
       temp_init(SPFLIB_TEMP_CAPACITY);    \
       return __real_main(argc, argv);     \
    }                                      \
    s32 __real_main(s32 argc, char** argv)

#if !defined(SPFLIB_TEMP_IMPL)

void temp_init(size_t capacity);
void* temp_alloc(size_t size);
void temp_storage_reset();

#else // !defined(SPFLIB_TEMP_IMPL)

inline void temp_init(size_t capacity)
{
#if defined(SPFLIB_MEMORY)
    __temp_storage.data = mem_alloc(capacity);
#else
    __temp_storage.data = malloc(capacity);
#endif

#if defined(SPF_WILL_ASSERT)
    SPF_ASSERT(__temp_storage.data != nullptr, "Temporary storage failed to initialize.");
#endif

    __temp_storage.capacity  = capacity;
    __temp_storage.pos_bytes = 0;
}

inline void* temp_alloc(size_t size)
{
    if (__temp_storage.data == nullptr) return nullptr;
    if ((size + __temp_storage.pos_bytes) >= __temp_storage.capacity) {
#if defined(SPF_WILL_ASSERT)
        SPF_ASSERT(0, "Temporary storage capacity exceeded. Did you forget to call 'temp_storage_reset()'?");
#endif
        return nullptr;
    }

    __temp_storage.data      += size;
    __temp_storage.pos_bytes += size;

    return __temp_storage.data;
}

inline void temp_storage_reset()
{
    __temp_storage.data      -= __temp_storage.pos_bytes;
    __temp_storage.pos_bytes  = 0;
}

#endif // !defined(SPFLIB_TEMP_IMPL)

#endif // defined(SPFLIB_TEMP)

